layer.css:
[data-ryt="footer"] { color: var(--ryt-text); border-top: 1px solid var(--ryt-border); font-style: normal; letter-spacing: normal; text-transform: none }
article[data-ryt="rec-card"] { background-color: var(--ryt-surface); border-top: 1px solid var(--ryt-border); border-right: 1px solid var(--ryt-border); border-bottom: 1px solid var(--ryt-border); border-left: 1px solid var(--ryt-border); border-radius: 12px; transition: border-color 0.2s, background-color 0.2s, box-shadow 0.2s }
[data-ryt="brand"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 700; font-style: normal; line-height: 1.5; letter-spacing: -0.4px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="nav"] a { color: color-mix(in srgb, var(--ryt-accent) 72%, transparent); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 13.5px; font-weight: 500; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: color-mix(in srgb, var(--ryt-accent) 72%, transparent); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: color 0.15s }
[data-ryt="header"] { border-bottom: 1px solid rgba(0, 0, 0, 0); border-top: none }
[data-ryt="button"] { color: color-mix(in srgb, var(--ryt-text) 85%, transparent); background-color: var(--ryt-surface); border-top: 1px solid var(--ryt-border); border-right: 1px solid var(--ryt-border); border-bottom: 1px solid var(--ryt-border); border-left: 1px solid var(--ryt-border); border-radius: 8px; font-family: "JetBrains Mono", "SF Mono", Menlo, Consolas, "Liberation Mono", monospace; font-weight: 500; font-style: normal; line-height: 1; letter-spacing: 0.6px; text-transform: uppercase; text-decoration-style: solid; text-decoration-color: color-mix(in srgb, var(--ryt-text) 85%, transparent); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 12px; padding-bottom: 0px; padding-left: 12px; transition: color 0.15s, background-color 0.15s, border-color 0.15s }
[data-ryt="review"] { color: var(--ryt-muted); font-family: var(--ryt-font-heading); font-size: 13px; font-weight: 400; font-style: normal; line-height: 1.625; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: var(--ryt-muted); font-family: "JetBrains Mono", "SF Mono", Menlo, Consolas, "Liberation Mono", monospace; font-size: 11px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 600; font-style: normal; line-height: 1.375; letter-spacing: -0.4px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: color 0.15s cubic-bezier(0.4, 0, 0.2, 1), background-color 0.15s cubic-bezier(0.4, 0, 0.2, 1), border-color 0.15s cubic-bezier(0.4, 0, 0.2, 1), outline-color 0.15s cubic-bezier(0.4, 0, 0.2, 1), text-decoration-color 0.15s cubic-bezier(0.4, 0, 0.2, 1), fill 0.15s cubic-bezier(0.4, 0, 0.2, 1), stroke 0.15s cubic-bezier(0.4, 0, 0.2, 1), --tw-gradient-from 0.15s cubic-bezier(0.4, 0, 0.2, 1), --tw-gradient-via 0.15s cubic-bezier(0.4, 0, 0.2, 1), --tw-gradient-to 0.15s cubic-bezier(0.4, 0, 0.2, 1) }
[data-ryt="button"]:hover { background-color: #ebe8e0; color: #3d3629 }
[data-ryt="nav"] a:hover { color: #3d3629 }
article[data-ryt="rec-card"]:hover { box-shadow: 0 1px 2px #3d3629, 0 10px 28px -14px #3d3629; box-shadow: 0 1px 2px color-mix(in oklab, #3d3629 4%, transparent), 0 10px 28px -14px color-mix(in oklab, #3d3629 16%, transparent) }
